import { test, expect } from '@playwright/test';

test.describe('Document Language Declaration', () => {
  let baseUrl: string;

  test.beforeEach(async ({ page }) => {
    baseUrl = process.env.BASE_URL || 'http://localhost:3000';
    await page.goto(baseUrl);
  });

  test('should have lang attribute declared on html element', async ({ page }) => {
    const htmlElement = page.locator('html');
    const langAttribute = await htmlElement.getAttribute('lang');

    expect(langAttribute).toBeTruthy();
    expect(langAttribute).toMatch(/^[a-z]{2}(-[A-Z]{2})?$/);
  });

  test('should have valid language code in lang attribute', async ({ page }) => {
    const htmlElement = page.locator('html');
    const langAttribute = await htmlElement.getAttribute('lang');

    const validLanguageCodes = [
      'en', 'en-US', 'en-GB', 'es', 'es-ES', 'fr', 'fr-FR', 
      'de', 'de-DE', 'it', 'it-IT', 'pt', 'pt-BR', 'ja', 'zh', 'zh-CN'
    ];

    expect(langAttribute).toBeTruthy();
    expect(validLanguageCodes).toContain(langAttribute);
  });

  test('should have lang attribute matching document content language', async ({ page }) => {
    const htmlElement = page.locator('html');
    const langAttribute = await htmlElement.getAttribute('lang');

    expect(langAttribute).not.toBeNull();
    expect(langAttribute?.length).toBeGreaterThan(0);

    const langCode = langAttribute?.split('-')[0];
    expect(langCode).toMatch(/^[a-z]{2}$/);
  });

  test('should not have empty lang attribute', async ({ page }) => {
    const htmlElement = page.locator('html');
    const langAttribute = await htmlElement.getAttribute('lang');

    expect(langAttribute).not.toBe('');
    expect(langAttribute).not.toBeNull();
  });

  test('should have lang attribute accessible to screen readers', async ({ page }) => {
    const htmlElement = page.locator('html');

    const langAttribute = await htmlElement.getAttribute('lang');
    expect(langAttribute).toBeTruthy();

    const ariaLabel = await htmlElement.getAttribute('aria-label');
    const role = await htmlElement.getAttribute('role');

    expect(langAttribute).toBeDefined();
  });

  test('should maintain lang attribute across page navigation', async ({ page }) => {
    const htmlElement = page.locator('html');
    const initialLang = await htmlElement.getAttribute('lang');

    expect(initialLang).toBeTruthy();

    const links = page.getByRole('link');
    const linkCount = await links.count();

    if (linkCount > 0) {
      const firstLink = links.first();
      const href = await firstLink.getAttribute('href');

      if (href && !href.startsWith('http') && !href.startsWith('mailto')) {
        await firstLink.click();
        await page.waitForLoadState('networkidle');

        const newLang = await htmlElement.getAttribute('lang');
        expect(newLang).toBe(initialLang);
      }
    }
  });
});
